import { BadgeFault } from './fault.js';
export function verifyBadge(badge: { conference: string; revoked: boolean }) {
  if (badge.conference !== 'aurora-26') throw new BadgeFault('BADGE_OTHER_EVENT');
  if (badge.revoked) throw new BadgeFault('BADGE_REVOKED');
}

